def step(context):
    world = context['inputs']['publication'][0]['payload']
    recipients = sorted(agent['id'] for agent in world['ecosystem']['agents'] if agent['can_author'] and agent['is_active'])
    rows = []
    for paper in world['papers']['papers']:
        owners = paper['author_id'] if isinstance(paper['author_id'], list) else [paper['author_id']]
        if not any(owner in recipients for owner in owners):
            continue
        history = paper.get('review_history', [])
        if not history:
            continue
        raw_reviews = [review for decision in history for review in decision.get('reviews', [])]
        scores = [review['overall_score'] for review in raw_reviews]
        rows.append({'paper_id':paper['id'], 'title':paper['title'], 'abstract':paper['abstract'],
                     'author_ids':owners, 'status':paper['status'], 'history':history,
                     'raw_review_count':len(scores),
                     'raw_peer_mean':sum(scores) / len(scores) if scores else None})
    feedback = {'year':context['period'], 'recipients':recipients, 'rows':rows,
                'cooperative':world.get('open_domain', {}).get('actors', {}).get('evidence-commons')}
    return {'outputs':{'feedback':[{'payload':feedback}]},
            'state':{'annual_evidence_counts':context['state'].get('annual_evidence_counts', []) + [sum(row['raw_review_count'] for row in rows)]}}

