import copy

def step(context):
    plan = context['inputs']['plans'][0]['payload']
    year = context['period']
    receipts = context['inputs'].get('previous',[])
    if len(receipts) > 1:
        raise ValueError('one explicitly wired previous-publication receipt expected')
    previous = receipts[0]['payload'] if receipts else None
    if previous is not None and previous['source_year'] != year - 1:
        raise ValueError('publication receipt must come from the immediately preceding interval')
    outcomes = previous['actors'] if previous is not None else {}
    orders = []
    for assignment in plan['assignments']:
        late = assignment['project_end_year'] > year
        if not late and context['parameters']['amendment_scope'] == 'late-only':
            continue
        amended = copy.deepcopy(assignment)
        amended['direction']['years'] = 1
        amended['project_start_year'] = year
        amended['project_end_year'] = year
        past = outcomes.get(assignment['actor_id'])
        focus_share = round(100 * context['parameters']['completion_focus'])
        instruction = ' Allocate ' + str(focus_share) + '% of the stated effort to a concrete result that can be written this interval; keep the actual researcher-selected topic and evidence.'
        if past is None:
            instruction += ' There is no previous-interval receipt available; do not infer a past outcome.'
        elif past['accepted_count'] == 0:
            instruction += ' The actual previous interval recorded no accepted result for this author. Narrow the deliverable rather than extending its completion date.'
        else:
            instruction += ' Previous actual accepted output count: ' + str(past['accepted_count']) + '. Build a bounded follow-up; actual prior paper IDs: ' + ', '.join(past['paper_ids']) + '.'
        amended['detailed_focus'] = assignment['detailed_focus'] + instruction
        amended['reason'] = 'Deadline-completeness contract informed only by observed prior publication receipts'
        orders.append(amended)
    return {'outputs':{'orders':[{'payload':{'year':year,'assignments':orders,
                'receipt_source_year':previous['source_year'] if previous else None}}]},
            'state':{'years':context['state'].get('years',0)+1,
                     'last_order_count':len(orders),'last_receipt_year':previous['source_year'] if previous else None}}

