                    'target_year':packet['year'],'assignment':assignment,'submit':True}}
                  for assignment in packet['assignments']]
    return {'outputs':{'amendments':amendments},
            'state':{'last_year':context['period'],'amended':len(amendments)}}

def step(context):
    world = context['inputs']['publication'][0]['payload']
    year = context['period']
    actors = {a['id']:{'accepted_count':0,'paper_ids':[]}
              for a in world['ecosystem']['agents'] if a['can_author']}
    for paper in world['papers']['papers']:
        accepted = sum(r.get('decision') == 'accept' and r['year'] == year
                       for r in paper['review_history'])
        if not accepted:
            continue
        authors = paper['author_id'] if isinstance(paper['author_id'],list) else [paper['author_id']]
        for author in authors:
            if author in actors:
                actors[author]['accepted_count'] += accepted
                actors[author]['paper_ids'].append(paper['id'])
    receipt = {'schema':'annual-publication-receipt-v8','source_year':year,'actors':actors}
    return {'outputs':{'receipt':[{'payload':receipt}]},
            'state':{'last_source_year':year,'actual_accepted_authorships':sum(a['accepted_count'] for a in actors.values())}}

